--
-- Table structure for table `quiz_results`
--

DROP TABLE IF EXISTS `quiz_results`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quiz_results` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned DEFAULT NULL,
  `deck_id` bigint unsigned NOT NULL,
  `question_type` enum('multiple_choice','written','flashcard') COLLATE utf8mb4_unicode_ci NOT NULL,
  `direction` enum('en-vi','vi-en') COLLATE utf8mb4_unicode_ci NOT NULL,
  `correct` int unsigned NOT NULL DEFAULT '0',
  `review` int unsigned NOT NULL DEFAULT '0',
  `total` int unsigned NOT NULL DEFAULT '0',
  `progress_segments` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
