--
-- Table structure for table `study_sessions`
--

DROP TABLE IF EXISTS `study_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `study_sessions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned DEFAULT NULL,
  `deck_id` bigint unsigned NOT NULL,
  `mode` enum('flashcard','quiz','written') COLLATE utf8mb4_unicode_ci NOT NULL,
  `direction` enum('en-vi','vi-en') COLLATE utf8mb4_unicode_ci NOT NULL,
  `only_favorite` tinyint(1) NOT NULL DEFAULT '0',
  `random_order` tinyint(1) NOT NULL DEFAULT '0',
  `started_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `ended_at` timestamp NULL DEFAULT NULL,
  `total` int unsigned NOT NULL DEFAULT '0',
  `correct` int unsigned NOT NULL DEFAULT '0',
  `review` int unsigned NOT NULL DEFAULT '0',
  `xp_earned` int unsigned NOT NULL DEFAULT '0',
  `max_combo` int unsigned NOT NULL DEFAULT '0',
  `segment_size` int unsigned NOT NULL DEFAULT '0',
  `segment_total` int unsigned NOT NULL DEFAULT '0',
  `segment_completed` int unsigned NOT NULL DEFAULT '0',
  `progress_segments` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_study_sessions_user_id` (`user_id`),
  KEY `idx_study_sessions_deck_id` (`deck_id`),
  KEY `idx_study_sessions_created` (`started_at`),
  CONSTRAINT `fk_study_sessions_deck` FOREIGN KEY (`deck_id`) REFERENCES `decks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_study_sessions_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=214 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

