  `user_id` bigint unsigned NOT NULL,
  `default_direction` enum('en-vi','vi-en') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'en-vi',
  `only_favorite` tinyint(1) NOT NULL DEFAULT '0',
  `random_order` tinyint(1) NOT NULL DEFAULT '0',
  `reward_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `reward_trigger_count` int unsigned NOT NULL DEFAULT '2',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_id` (`user_id`),
  CONSTRAINT `fk_user_settings_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
